use tauri::{AppHandle,Manager};
use crate::{clipboard,models::ScrollDirection,overlays,settings_store,state::AppState};
pub fn navigate(app:&AppHandle,mut delta:i32)->Result<(),String>{let state=app.state::<AppState>();let s=state.settings.read().clone();if matches!(s.history.scroll_direction,ScrollDirection::Reversed){delta=-delta}let len=state.history.lock().len();if len==0{return Ok(())}{let mut sel=state.selector.lock();if !sel.active{return Ok(())}let current=sel.selected_index as i32;let next=current+delta;if s.history.wrap_selection{sel.selected_index=next.rem_euclid(len as i32) as usize}else{sel.selected_index=next.clamp(0,len as i32-1) as usize;}}overlays::emit_selection(app)}
pub fn accept(app:&AppHandle)->Result<(),String>{let state=app.state::<AppState>();let (active,index)={let mut s=state.selector.lock();let x=(s.active,s.selected_index);s.active=false;x};if !active{overlays::hide_history(app);return Ok(())}let settings=state.settings.read().clone();let item=state.history.lock().get(index);if let Some(item)=item{clipboard::write_text(app,&item.content)?;if settings.history.move_selected_to_top{state.history.lock().promote(&item.id);let items=state.history.lock().items();settings_store::save_history(app,settings.history.persist_history,&items)?;}}overlays::hide_history(app);Ok(())}
pub fn cancel(app:&AppHandle){app.state::<AppState>().selector.lock().active=false;overlays::hide_history(app)}
#[cfg(test)]mod tests{#[test]fn clamp_math(){let len=3_i32;assert_eq!((1+10).clamp(0,len-1),2);assert_eq!((1-10).clamp(0,len-1),0)}#[test]fn wrap_math(){assert_eq!((-1_i32).rem_euclid(3),2);assert_eq!(3_i32.rem_euclid(3),0)}}
